    "description": "36氪获悉，中铝国际公告，公司中标越南平福矿业年产240万吨氧化铝项目，合同总价8.33亿美元，折合人民币约55.95亿元。项目采用EPC总承包形式，工期27个月，工作范围包括设计、设备供应、施工及试运行等。若合同顺利实施，将扩大公司经营规模，提升持续盈利能力，但具体财务影响尚无法测算。项目位于境外，存在政治、法律及外汇等海外经营风险。",
