    "description": "36氪获悉，深科技公告，公司拟通过深圳联合产权交易所公开挂牌出售所持昂纳科技全部股权，持股比例为17.034%，挂牌底价将不低于昂纳科技股东全部权益评估值130.1亿元的17.034%。本次交易预计将为公司带来不低于20.5亿元税前利润，交易完成后公司将不再持有昂纳科技股份。本次交易尚需经股东会审议，交易对象、价格及时间尚未确定，能否成交存在不确定性。",
