    "content": "新华社日内瓦10月26日电（记者王其冰）10月25日是新中国恢复联合国合法席位55周年纪念日。中国常驻联合国日内瓦办事处和瑞士其他国际组织代表贾桂德在为此撰写的文章《从日内瓦看新中国与联合国的55年》中表示，新中国与联合国55年风雨兼程，日内瓦见证中国多边外交历史时刻，中国愿同各方携手加强联合国作用、弘扬多边主义。 贾桂德在文章中说，1971年10月25日，第26届联大以压倒性多数通过第2758号决议，决定恢复中华人民共和国在联合国的一切权利，承认中华人民共和国政府代表是中国在联合国的唯一合法代表。这标志着占世界人…"
