    "description": "新华社基辅10月26日电（记者李东旭）据乌克兰最高拉达（议会）官网26日发布的消息，乌克兰总统泽连斯基当天向最高拉达递交了关于继续延长国家战时状态90天的法令草案。 法令草案提议将乌克兰国家战时状态从10月31日延长至2027年1月29日。 乌克兰国家通讯社报道称，自2022年初俄乌冲突升级以来，乌最高拉达此前已先后20次批准延长国家战时状态。",
    "content": "新华社基辅10月26日电（记者李东旭）据乌克兰最高拉达（议会）官网26日发布的消息，乌克兰总统泽连斯基当天向最高拉达递交了关于继续延长国家战时状态90天的法令草案。 法令草案提议将乌克兰国家战时状态从10月31日延长至2027年1月29日。 乌克兰国家通讯社报道称，自2022年初俄乌冲突升级以来，乌最高拉达此前已先后20次批准延长国家战时状态。"
