    "content": "根据党中央关于巡视工作的统一部署，近日，二十届中央第八轮巡视完成进驻工作。15个中央巡视组将对教育部和31所中管高校党组织开展常规巡视。 被巡视单位分别召开巡视进驻动员会。各中央巡视组组长作动员讲话，对深入学习贯彻习近平总书记关于巡视工作的重要讲话精神，扎实开展巡视工作提出要求。 各中央巡视组组长指出，党的十八大以来，以习近平同志为核心的党中央把巡视作为加强党的建设的重要举措、党内监督的战略性制度安排，引领巡视工作守正创新、深化发展，巡视成为管党治党利剑、治国理政利器。教育是国之大计、党之大计，高等教育是建设教育强…"
