    "description": "安徽省招标采购协会10月26日通报称清退3名评标评审专家。 经排查，安徽省招标采购协会专家库的3名评标评审专家存在弄虚作假骗取入库行为。根据《安徽省招标采购协会专家库管理办法》(皖招协[2025]2号)第十二条规定，将3人退出安徽省招标采购协会专家库，并在安徽省招标投标信息网予以公告。希望各位评标评审专家引以为戒，在申请入选专家库之前以及在库履职过程中，严格遵守法律政策规定，信守入库承诺，共同维护公共资源交易市场的公平公正及严肃性。",
    "content": "安徽省招标采购协会10月26日通报称清退3名评标评审专家。 经排查，安徽省招标采购协会专家库的3名评标评审专家存在弄虚作假骗取入库行为。根据《安徽省招标采购协会专家库管理办法》(皖招协[2025]2号)第十二条规定，将3人退出安徽省招标采购协会专家库，并在安徽省招标投标信息网予以公告。希望各位评标评审专家引以为戒，在申请入选专家库之前以及在库履职过程中，严格遵守法律政策规定，信守入库承诺，共同维护公共资源交易市场的公平公正及严肃性。"
