    "content": "中国商务部星期一（10月26日）发布《保护中国商业秘密特别规定（征求意见稿）》，拟对危害或实际威胁中国国家主权、安全或发展利益，侵害中国商业秘密的外国实体采取措施。 根据征求意见稿，相关措施包括限制或禁止这些实体在中国新增投资，以及从事与中国有关的货物、技术进出口以及国际服务贸易活动；禁止向其出口相关物项；限制或禁止其相关人员、交通运输工具等入境，以及限制或取消相关人员在中国境内工作许可、停留或者居留资格等。 商务部称，上述意见稿是为了维护国家主权、安全、发展利益，以及保护中国权利人的合法权益。意见反馈截止日期为1…"
