    "content": "新华社北京10月26日电 记者手记：乒乓球削球手的春天到了吗？ 新华社记者岳冉冉、苏斌 10月25日，塔什干之夜，国乒19岁“削球手”李天阳把球拍擦了又擦。 亚锦赛男单决赛，他2:3输给张本智和，拿到亚军。比分是11:1、11:9、7:11、8:11、7:11。前两局，他“削”得张本智和接发球出界、相持发懵；三四局张本智和加快节奏、变化落点；决胜局李天阳追到7平，最后几个关键球紧张了，被翻了盘。 虽然没拿到金牌，但他把男线削球手重新带回洲际大赛决赛舞台。不只李天阳，韩国削球手姜东秀同样闪光，他先在团体赛把张本智和打…"
